1	// The only module that talks to the Shipyard HTTP API.
2	
3	async function getJson(url, label) {
4	  try {
5	    const res = await fetch(url);
6	    if (!res.ok) throw new Error(`HTTP ${res.status}`);
7	    return await res.json();
8	  } catch (err) {
9	    console.error(`Could not load ${label}`, err);
10	    return [];
11	  }
12	}
13	
14	export function fetchTasks() {
15	  return getJson("/api/tasks", "tasks");
16	}
17	
18	export function fetchNotes({ q = "", tag = "" } = {}) {
19	  const params = new URLSearchParams();
20	  if (q) params.set("q", q);
21	  if (tag) params.set("tag", tag);
22	  return getJson(`/api/notes?${params}`, "notes");
23	}
