1	// DOM rendering. Each function owns one region of index.html and reads only the state it is given.
2	
3	import { allTags, computeKpis, escapeHtml, filterTasks, formatBody, isOverdue, uniqueOwners } from "./logic.js";
4	
5	const $ = (id) => document.getElementById(id);
6	
7	export function renderKpis(state) {
8	  const k = computeKpis(state.tasks, state.notes);
9	  $("kpi-open").textContent = k.open;
10	  $("kpi-done").textContent = k.done;
11	  $("kpi-overdue").textContent = k.overdue;
12	  $("kpi-notes").textContent = k.notes;
13	}
14	
15	export function renderOwnerFilter(state) {
16	  const select = $("owner-filter");
17	  const current = select.value;
18	  select.innerHTML = '<option value="">All owners</option>' +
19	    uniqueOwners(state.tasks).map((o) => `<option value="${escapeHtml(o)}">${escapeHtml(o)}</option>`).join("");
20	  select.value = current;
21	}
22	
23	export function renderTasks(state) {
24	  const rows = filterTasks(state.tasks, state);
25	  $("tasks-body").innerHTML = rows.map((t) => `
26	    <tr class="${isOverdue(t) ? "overdue" : ""}">
27	      <td>${escapeHtml(t.title)}</td>
28	      <td>${escapeHtml(t.owner || "–")}</td>
29	      <td>${escapeHtml(t.due || "–")}</td>
30	      <td><span class="status status-${t.status}">${t.status}</span></td>
31	    </tr>`).join("");
32	  $("tasks-empty").hidden = rows.length > 0;
33	}
34	
35	export function renderTags(state, onToggle) {
36	  const box = $("tag-chips");
37	  box.innerHTML = allTags(state.notes).map((tag) =>
38	    `<button class="chip ${tag === state.tag ? "active" : ""}" data-tag="${escapeHtml(tag)}">#${escapeHtml(tag)}</button>`).join("");
39	  box.querySelectorAll(".chip").forEach((chip) => chip.addEventListener("click", () => onToggle(chip.dataset.tag)));
40	}
41	
42	export function renderNotes(state) {
43	  $("notes-list").innerHTML = state.notes.map((n) => `
44	    <li>
45	      <h3>${escapeHtml(n.title)}</h3>
46	      <p>${formatBody(n.body)}</p>
47	      <div class="note-tags">${(n.tags || []).map((t) => `<span>#${escapeHtml(t)}</span>`).join("")}</div>
48	    </li>`).join("");
49	  $("notes-empty").hidden = state.notes.length > 0;
50	}
51	
52	export function renderUpdated() {
53	  $("last-updated").textContent = `updated ${new Date().toLocaleTimeString()}`;
54	}
