1	// Entry point: owns the state object and wires events to data loading and rendering.
2	
3	import { fetchNotes, fetchTasks } from "./api.js";
4	import { renderKpis, renderNotes, renderOwnerFilter, renderTags, renderTasks, renderUpdated } from "./render.js";
5	
6	const state = { tasks: [], notes: [], owner: "", status: "pending", q: "", tag: "" };
7	
8	async function refreshNotes() {
9	  state.notes = await fetchNotes(state);
10	  renderNotes(state);
11	  renderTags(state, toggleTag);
12	  renderKpis(state);
13	}
14	
15	function toggleTag(tag) {
16	  state.tag = state.tag === tag ? "" : tag;
17	  return refreshNotes();
18	}
19	
20	async function init() {
21	  document.getElementById("owner-filter").addEventListener("change", (e) => {
22	    state.owner = e.target.value;
23	    renderTasks(state);
24	  });
25	  document.getElementById("status-filter").addEventListener("change", (e) => {
26	    state.status = e.target.value;
27	    renderTasks(state);
28	  });
29	  let timer;
30	  document.getElementById("notes-search").addEventListener("input", (e) => {
31	    clearTimeout(timer);
32	    timer = setTimeout(() => {
33	      state.q = e.target.value.trim();
34	      refreshNotes();
35	    }, 200);
36	  });
37	  [state.tasks, state.notes] = await Promise.all([fetchTasks(), fetchNotes(state)]);
38	  renderKpis(state);
39	  renderOwnerFilter(state);
40	  renderTasks(state);
41	  renderTags(state, toggleTag);
42	  renderNotes(state);
43	  renderUpdated();
44	}
45	
46	init();
