1	// Pure, DOM-free rules for the release dashboard. Covered by dashboard/tests/logic.test.mjs.
2	
3	export function todayIso(now = new Date()) {
4	  return now.toISOString().slice(0, 10);
5	}
6	
7	export function isOverdue(task, today = todayIso()) {
8	  return task.status !== "done" && Boolean(task.due) && task.due < today;
9	}
10	
11	export function filterTasks(tasks, { owner = "", status = "pending" } = {}) {
12	  return tasks
13	    .filter((t) => (status === "all" ? true : t.status === status))
14	    .filter((t) => (owner ? t.owner === owner : true))
15	    .sort((a, b) => (a.due || "9999-12-31").localeCompare(b.due || "9999-12-31") || a.id - b.id);
16	}
17	
18	export function computeKpis(tasks, notes, today = todayIso()) {
19	  return {
20	    open: tasks.filter((t) => t.status !== "done").length,
21	    done: tasks.filter((t) => t.status === "done").length,
22	    overdue: tasks.filter((t) => isOverdue(t, today)).length,
23	    notes: notes.length,
24	  };
25	}
26	
27	export function uniqueOwners(tasks) {
28	  return [...new Set(tasks.map((t) => t.owner).filter(Boolean))].sort();
29	}
30	
31	export function allTags(notes) {
32	  return [...new Set(notes.flatMap((n) => n.tags || []))].sort();
33	}
34	
35	export function escapeHtml(text) {
36	  return String(text ?? "")
37	    .replaceAll("&", "&amp;")
38	    .replaceAll("<", "&lt;")
39	    .replaceAll(">", "&gt;")
40	    .replaceAll('"', "&quot;");
41	}
42	
43	export function formatBody(body) {
44	  return String(body ?? "").replace(/\*\*(.+?)\*\*/g, "<strong>$1</strong>");
45	}
